// ====================================================
// VALIDATOR MIDDLEWARE
// Set msg.schema before this node.
//
// Outputs:
//   1 → Form redirect (302)        → wire to http response
//   2 → Fetch error (400 JSON)     → wire to http response
//   3 → Valid payload              → go to business logic
// ====================================================

// ─────────────────────────────────────────────
// TYPE VALIDATORS
// ─────────────────────────────────────────────



function validateString(field, val, rules, errors) {
    val = String(val).trim();
    if (/<[^>]*>/.test(val)) {
        errors.push({ field, message: rules.messages?.html || `${field} contains invalid characters` });
        return null;
    }
    if (rules.minLen && val.length < rules.minLen)
        errors.push({ field, message: rules.messages?.minLen || `${field} must be at least ${rules.minLen} characters` });
    if (rules.maxLen && val.length > rules.maxLen)
        errors.push({ field, message: rules.messages?.maxLen || `${field} exceeds max length of ${rules.maxLen}` });
    if (rules.pattern && !new RegExp(rules.pattern).test(val))
        errors.push({ field, message: rules.messages?.pattern || `${field} has an invalid format` });
    return val;
}

function validateNumber(field, val, rules, errors) {
    if (rules.pattern && !new RegExp(rules.pattern).test(String(val))) {
        errors.push({ field, message: rules.messages?.pattern || `${field} has an invalid format` });
        return null;
    }
    val = Number(val);
    if (isNaN(val)) {
        errors.push({ field, message: rules.messages?.type || `${field} must be a number` });
        return null;
    }
    if (rules.min !== undefined && val < rules.min)
        errors.push({ field, message: rules.messages?.min || `${field} must be at least ${rules.min}` });
    if (rules.max !== undefined && val > rules.max)
        errors.push({ field, message: rules.messages?.max || `${field} must be at most ${rules.max}` });
    if (rules.precision !== undefined)
        val = parseFloat(val.toFixed(rules.precision));
    return val;
}

function validateBoolean(field, val, rules, errors) {
    if (val === true || val === 'true' || val === 1 || val === '1' || val === 'on') return true;
    if (val === false || val === 'false' || val === 0 || val === '0' || val === 'off') return false;
    errors.push({ field, message: rules.messages?.type || `${field} must be a boolean` });
    return null;
}

function validateDate(field, val, rules, errors) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(val) || isNaN(Date.parse(val))) {
        errors.push({ field, message: rules.messages?.type || `${field} must be a valid date (YYYY-MM-DD)` });
        return null;
    }
    return val;
}

function validateAllowedValues(field, val, rules, errors) {
    if (rules.allowedValues && !rules.allowedValues.includes(val)) {
        errors.push({ field, message: rules.messages?.allowedValues || `${field} has an invalid value` });
        return null;
    }
    return val;
}

function buildRowMessages(rules, row) {
    if (!rules.messages) return {};
    const out = {};
    for (const [k, v] of Object.entries(rules.messages)) out[k] = `${v} ${row}`;
    return out;
}

function validateArrayItem(field, item, idx, itemSchema, errors, strictItems) {
    const cleaned = {};
    const row = `in row ${idx + 1}`;

    if (strictItems) {
        for (const key of Object.keys(item)) {
            if (!(key in itemSchema))
                errors.push({ field: `${field}[${idx}].${key}`, message: `Unknown field: ${key} ${row}` });
        }
    }

    for (const [subField, subRules] of Object.entries(itemSchema)) {
        let subVal = item[subField];
        const key = `${field}[${idx}].${subField}`;
        const rulesWithRowMsg = { ...subRules, messages: { ...subRules.messages, ...buildRowMessages(subRules, row) } };

        if (subRules.required && (subVal === undefined || subVal === null || subVal === '')) {
            errors.push({
                field: key,
                message: subRules.messages?.required
                    ? `${subRules.messages.required} ${row}`
                    : `${subField} is required ${row}`
            });
            continue;
        }
        if (subVal === undefined || subVal === null || subVal === '') continue;

        if (subRules.type === 'string') subVal = validateString(key, subVal, rulesWithRowMsg, errors);
        if (subRules.type === 'number') subVal = validateNumber(key, subVal, rulesWithRowMsg, errors);
        if (subRules.type === 'boolean') subVal = validateBoolean(key, subVal, rulesWithRowMsg, errors);
        if (subRules.type === 'date') subVal = validateDate(key, subVal, rulesWithRowMsg, errors);

        if (subVal !== null && subVal !== undefined && subRules.allowedValues)
            subVal = validateAllowedValues(key, subVal, rulesWithRowMsg, errors);

        if (subVal !== null && subVal !== undefined) cleaned[subField] = subVal;
    }
    return cleaned;
}

function validateArray(field, val, rules, errors, strictItems) {
    if (!Array.isArray(val)) {
        errors.push({ field, message: rules.messages?.type || `${field} must be an array` });
        return null;
    }
    if (rules.minItems && val.length < rules.minItems) {
        errors.push({ field, message: rules.messages?.minItems || `${field} must have at least ${rules.minItems} item(s)` });
        return null;
    }
    if (rules.maxItems && val.length > rules.maxItems) {
        errors.push({ field, message: rules.messages?.maxItems || `${field} must have at most ${rules.maxItems} item(s)` });
        return null;
    }
    if (!rules.itemSchema) return val;
    return val.map((item, idx) => validateArrayItem(field, item, idx, rules.itemSchema, errors, strictItems));
}


// ─────────────────────────────────────────────
// MAIN
// ─────────────────────────────────────────────

const SCHEMA = msg.schema;
const isFetchRequest = msg.isFetchRequest;   // set by AUTH_MIDDLEWARE

if (!SCHEMA || typeof SCHEMA !== 'object') {
    msg.statusCode = 500;
    msg.payload = { success: false, errors: [{ field: null, message: 'Server error: schema not defined' }] };
    return [null, msg, null];   // Output 2 (fetch-style — server fault, not form fault)
}

const data = msg.payload;
node.warn(data);

if (!data || typeof data !== 'object' || Array.isArray(data)) {
    msg.statusCode = 400;
    msg.payload = { success: false, errors: [{ field: null, message: 'Invalid request body' }] };
    return [null, msg, null];   // Output 2
}

const errors = [];
const cleaned = {};

const isStrict = SCHEMA._strict !== false;
const isStrictItems = SCHEMA._strictItems !== false;

// Unknown field rejection (top level)
if (isStrict) {
    const reservedKeys = new Set(['_strict', '_strictItems']);
    for (const key of Object.keys(data)) {
        if (!reservedKeys.has(key) && !(key in SCHEMA))
            errors.push({ field: key, message: `Unknown field: ${key}` });
    }
}

// Field loop
for (const [field, rules] of Object.entries(SCHEMA)) {
    if (field === '_strict' || field === '_strictItems') continue;

    let val = data[field];

    if (rules.required && (val === undefined || val === null || val === '')) {
        errors.push({ field, message: rules.messages?.required || `${field} is required` });
        continue;
    }
    if (val === undefined || val === null || val === '') continue;

    if (rules.type === 'string') val = validateString(field, val, rules, errors);
    if (rules.type === 'number') val = validateNumber(field, val, rules, errors);
    if (rules.type === 'boolean') val = validateBoolean(field, val, rules, errors);
    if (rules.type === 'date') val = validateDate(field, val, rules, errors);
    if (rules.type === 'array') val = validateArray(field, val, rules, errors, isStrictItems);

    if (val !== null && val !== undefined && rules.type !== 'array' && rules.allowedValues)
        val = validateAllowedValues(field, val, rules, errors);

    if (val !== null && val !== undefined) cleaned[field] = val;
}

// ─────────────────────────────────────────────
// RESPOND
// ─────────────────────────────────────────────

if (errors.length > 0) {
    msg.statusCode = 400;

    if (!isFetchRequest) {
        // Output 1 → Form redirect with errors in query string
        const errorParam = encodeURIComponent(JSON.stringify(errors));
        const path = msg.errorRedirectPath || '/app/home';
        msg.statusCode = 302;
        msg.headers = { Location: `${path}?errors=${errorParam}` };
        msg.payload = 'Redirecting...';
        return [msg, null, null];
    }

    // Output 2 → Fetch JSON error
    msg.payload = { success: false, errors };
    return [null, msg, null];
}

// Output 3 → Valid
msg.payload = cleaned;
return [null, null, msg];

