// ─────────────────────────────────────────────
// SET SCHEMA NODE
// Place this function node just before Validator
// ─────────────────────────────────────────────

msg.schema = {

    // ── Strict mode flags ──────────────────────
    // _strict: false,        // uncomment to allow unknown top-level fields
    // _strictItems: false,   // uncomment to allow unknown fields inside array items


    // ── STRING: basic required ─────────────────
    name: {
        type: 'string',
        required: true,
        minLen: 2,
        maxLen: 80,
        messages: {
            required: 'Full name is required',
            minLen:   'Name must be at least 2 characters',
            maxLen:   'Name must not exceed 80 characters'
        }
    },


    // ── STRING: pattern (email format) ────────
    email: {
        type: 'string',
        required: true,
        maxLen: 255,
        pattern: '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$',
        messages: {
            required: 'Email is required',
            pattern:  'Enter a valid email address'
        }
    },


    // ── STRING: pattern (phone — raw string, not converted) ──
    phone: {
        type: 'string',
        required: false,
        pattern: '^\\+?[0-9]{7,15}$',
        messages: {
            pattern: 'Enter a valid phone number'
        }
    },


    // ── STRING: allowed values (enum) ─────────
    role: {
        type: 'string',
        required: true,
        allowedValues: ['admin', 'manager', 'operator'],
        messages: {
            required:      'Role is required',
            allowedValues: 'Role must be admin, manager, or operator'
        }
    },


    // ── STRING: optional with max length ──────
    notes: {
        type: 'string',
        required: false,
        maxLen: 500,
        messages: {
            maxLen: 'Notes must not exceed 500 characters'
        }
    },


    // ── NUMBER: integer with min/max ──────────
    age: {
        type: 'number',
        required: true,
        min: 0,
        max: 120,
        precision: 0,        // rounds to whole number
        messages: {
            required: 'Age is required',
            type:     'Age must be a number',
            min:      'Age must be 0 or above',
            max:      'Age must be 120 or below'
        }
    },


    // ── NUMBER: decimal with precision ────────
    price: {
        type: 'number',
        required: true,
        min: 0,
        precision: 2,        // rounds to 2 decimal places e.g. 19.999 → 20.00
        messages: {
            required: 'Price is required',
            type:     'Price must be a number',
            min:      'Price cannot be negative'
        }
    },


    // ── NUMBER: pattern checked BEFORE conversion
    //    (preserves raw format e.g. "007", pin codes) ──
    employeeCode: {
        type: 'number',
        required: false,
        pattern: '^\\d{3}$',   // must be exactly 3 digits e.g. "007" → kept as string before Number()
        messages: {
            pattern: 'Employee code must be exactly 3 digits'
        }
    },


    // ── BOOLEAN: required flag ────────────────
    //    accepts: true/false, "true"/"false", 1/0, "1"/"0", "on"/"off" (HTML checkbox)
    isActive: {
        type: 'boolean',
        required: true,
        messages: {
            required: 'Active status is required',
            type:     'Active status must be true or false'
        }
    },


    // ── BOOLEAN: optional checkbox ────────────
    //    HTML form checkboxes send "on" when checked, nothing when unchecked
    //    If unchecked the field is absent → optional handles it gracefully
    acceptsMarketing: {
        type: 'boolean',
        required: false
    },


    // ── DATE: required ────────────────────────
    //    format: YYYY-MM-DD only
    startDate: {
        type: 'date',
        required: true,
        messages: {
            required: 'Start date is required',
            type:     'Start date must be a valid date (YYYY-MM-DD)'
        }
    },


    // ── DATE: optional ────────────────────────
    endDate: {
        type: 'date',
        required: false,
        messages: {
            type: 'End date must be a valid date (YYYY-MM-DD)'
        }
    },


    // ── ARRAY: simple (no itemSchema) ─────────
    //    validates it is an array with at least 1 item
    //    items are passed through as-is (no per-item type checking)
    tags: {
        type: 'array',
        required: false,
        minItems: 1,
        maxItems: 10,
        messages: {
            type:     'Tags must be an array',
            minItems: 'Provide at least 1 tag',
            maxItems: 'Maximum 10 tags allowed'
        }
    },


    // ── ARRAY: with itemSchema (covers all sub-types) ──
    items: {
        type: 'array',
        required: true,
        minItems: 1,
        maxItems: 100,
        messages: {
            required: 'Order must have at least one item',
            type:     'Items must be an array',
            minItems: 'Order must have at least 1 item',
            maxItems: 'Order cannot exceed 100 items'
        },
        itemSchema: {

            // string — required, pattern
            sku: {
                type: 'string',
                required: true,
                maxLen: 40,
                pattern: '^[A-Z0-9\\-]+$',
                messages: {
                    required: 'SKU is required',
                    pattern:  'SKU must be uppercase letters, numbers, or hyphens'
                }
            },

            // string — allowed values
            category: {
                type: 'string',
                required: true,
                allowedValues: ['electronics', 'clothing', 'food'],
                messages: {
                    required:      'Category is required',
                    allowedValues: 'Category must be electronics, clothing, or food'
                }
            },

            // number — integer
            qty: {
                type: 'number',
                required: true,
                min: 1,
                max: 9999,
                precision: 0,
                messages: {
                    required: 'Quantity is required',
                    type:     'Quantity must be a number',
                    min:      'Quantity must be at least 1',
                    max:      'Quantity cannot exceed 9999'
                }
            },

            // number — decimal
            unitPrice: {
                type: 'number',
                required: true,
                min: 0,
                precision: 2,
                messages: {
                    required: 'Unit price is required',
                    type:     'Unit price must be a number',
                    min:      'Unit price cannot be negative'
                }
            },

            // number — pattern before conversion (e.g. barcode must be exactly 8 digits)
            barcode: {
                type: 'number',
                required: false,
                pattern: '^\\d{8}$',
                messages: {
                    pattern: 'Barcode must be exactly 8 digits'
                }
            },

            // boolean — e.g. gift wrap toggle per item
            isGift: {
                type: 'boolean',
                required: false
            },

            // date — per item dispatch date
            dispatchDate: {
                type: 'date',
                required: false,
                messages: {
                    type: 'Dispatch date must be YYYY-MM-DD'
                }
            },

            // string — optional notes per item
            itemNotes: {
                type: 'string',
                required: false,
                maxLen: 200
            }
        }
    }
};

// Error redirect path for form submissions (browser requests)
// Validator will redirect here with ?errors=... on validation failure
msg.errorRedirectPath = '/orders/new/';

return msg;

func:
// ====================================================
// VALIDATOR MIDDLEWARE
// Set msg.schema before this node.
//
// Outputs:
//   1 → Valid payload          → go to business logic
//   2 → Fetch error (400 JSON) → wire to http response
//   3 → Form error (302)       → wire to http response
// ====================================================


// ─────────────────────────────────────────────
// TYPE VALIDATORS
// ─────────────────────────────────────────────

function validateString(field, val, rules, errors) {
    val = String(val).trim();

    if (/<[^>]*>/.test(val)) {
        errors.push({ field, message: rules.messages?.html || `${field} contains invalid characters` });
        return null;
    }
    if (rules.minLen && val.length < rules.minLen) {
        errors.push({ field, message: rules.messages?.minLen || `${field} must be at least ${rules.minLen} characters` });
    }
    if (rules.maxLen && val.length > rules.maxLen) {
        errors.push({ field, message: rules.messages?.maxLen || `${field} exceeds max length of ${rules.maxLen}` });
    }
    if (rules.pattern && !new RegExp(rules.pattern).test(val)) {
        errors.push({ field, message: rules.messages?.pattern || `${field} has an invalid format` });
    }
    return val;
}

function validateNumber(field, val, rules, errors) {
    // Pattern check BEFORE conversion (preserves raw string format e.g. "007")
    if (rules.pattern && !new RegExp(rules.pattern).test(String(val))) {
        errors.push({ field, message: rules.messages?.pattern || `${field} has an invalid format` });
        return null;
    }

    val = Number(val);

    if (isNaN(val)) {
        errors.push({ field, message: rules.messages?.type || `${field} must be a number` });
        return null;
    }
    if (rules.min !== undefined && val < rules.min) {
        errors.push({ field, message: rules.messages?.min || `${field} must be at least ${rules.min}` });
    }
    if (rules.max !== undefined && val > rules.max) {
        errors.push({ field, message: rules.messages?.max || `${field} must be at most ${rules.max}` });
    }
    if (rules.precision !== undefined) {
        val = parseFloat(val.toFixed(rules.precision));
    }
    return val;
}

function validateBoolean(field, val, rules, errors) {
    // FIX 4: handle HTML form checkbox values ("on" / "off")
    if (val === true || val === 'true' || val === 1 || val === '1' || val === 'on') return true;
    if (val === false || val === 'false' || val === 0 || val === '0' || val === 'off') return false;

    errors.push({ field, message: rules.messages?.type || `${field} must be a boolean` });
    return null;
}

function validateDate(field, val, rules, errors) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(val) || isNaN(Date.parse(val))) {
        errors.push({ field, message: rules.messages?.type || `${field} must be a valid date (YYYY-MM-DD)` });
        return null;
    }
    return val;
}

function validateAllowedValues(field, val, rules, errors) {
    if (rules.allowedValues && !rules.allowedValues.includes(val)) {
        errors.push({ field, message: rules.messages?.allowedValues || `${field} has an invalid value` });
        return null;
    }
    return val;
}

// Appends "in row N" to custom messages for array item errors
function buildRowMessages(rules, row) {
    if (!rules.messages) return {};
    const out = {};
    for (const [k, v] of Object.entries(rules.messages)) {
        out[k] = `${v} ${row}`;
    }
    return out;
}

function validateArrayItem(field, item, idx, itemSchema, errors, strictItems) {
    const cleaned = {};
    const row = `in row ${idx + 1}`;

    // FIX 3: unknown field rejection inside array items
    if (strictItems) {
        for (const key of Object.keys(item)) {
            if (!(key in itemSchema)) {
                errors.push({ field: `${field}[${idx}].${key}`, message: `Unknown field: ${key} ${row}` });
            }
        }
    }

    for (const [subField, subRules] of Object.entries(itemSchema)) {
        let subVal = item[subField];
        const key = `${field}[${idx}].${subField}`;
        const rowMessages = buildRowMessages(subRules, row);
        const rulesWithRowMsg = { ...subRules, messages: { ...subRules.messages, ...rowMessages } };

        if (subRules.required && (subVal === undefined || subVal === null || subVal === '')) {
            errors.push({
                field: key, message: subRules.messages?.required
                    ? `${subRules.messages.required} ${row}`
                    : `${subField} is required ${row}`
            });
            continue;
        }
        if (subVal === undefined || subVal === null || subVal === '') continue;

        if (subRules.type === 'string') subVal = validateString(key, subVal, rulesWithRowMsg, errors);
        if (subRules.type === 'number') subVal = validateNumber(key, subVal, rulesWithRowMsg, errors);
        if (subRules.type === 'boolean') subVal = validateBoolean(key, subVal, rulesWithRowMsg, errors);
        if (subRules.type === 'date') subVal = validateDate(key, subVal, rulesWithRowMsg, errors);

        if (subVal !== null && subVal !== undefined && subRules.allowedValues) {
            subVal = validateAllowedValues(key, subVal, rulesWithRowMsg, errors);
        }

        if (subVal !== null && subVal !== undefined) cleaned[subField] = subVal;
    }
    return cleaned;
}

function validateArray(field, val, rules, errors, strictItems) {
    if (!Array.isArray(val)) {
        errors.push({ field, message: rules.messages?.type || `${field} must be an array` });
        return null;
    }
    if (rules.minItems && val.length < rules.minItems) {
        errors.push({ field, message: rules.messages?.minItems || `${field} must have at least ${rules.minItems} item(s)` });
        return null;
    }
    if (rules.maxItems && val.length > rules.maxItems) {
        errors.push({ field, message: rules.messages?.maxItems || `${field} must have at most ${rules.maxItems} item(s)` });
        return null;
    }
    if (!rules.itemSchema) return val;

    return val.map((item, idx) => validateArrayItem(field, item, idx, rules.itemSchema, errors, strictItems));
}


// ─────────────────────────────────────────────
// MAIN
// ─────────────────────────────────────────────

const SCHEMA = msg.schema;

if (!SCHEMA || typeof SCHEMA !== 'object') {
    msg.statusCode = 500;
    msg.payload = { success: false, errors: [{ field: null, message: 'Server error: schema not defined' }] };
    return [null, msg, null];
}

const data = msg.payload;

if (!data || typeof data !== 'object' || Array.isArray(data)) {
    msg.statusCode = 400;
    msg.payload = { success: false, errors: [{ field: null, message: 'Invalid request body' }] };
    return [null, msg, null];
}

const errors = [];
const cleaned = {};

// _strict controls unknown field rejection at top level
// _strictItems controls unknown field rejection inside array items
// both default to true (strict) — set false to opt out
const isStrict = SCHEMA._strict !== false;
const isStrictItems = SCHEMA._strictItems !== false;

// ── Unknown field rejection (top level) ──
if (isStrict) {
    const reservedKeys = new Set(['_strict', '_strictItems']);
    for (const key of Object.keys(data)) {
        if (!reservedKeys.has(key) && !(key in SCHEMA)) {
            errors.push({ field: key, message: `Unknown field: ${key}` });
        }
    }
}

// ── Field loop ──
for (const [field, rules] of Object.entries(SCHEMA)) {
    if (field === '_strict' || field === '_strictItems') continue;

    let val = data[field];

    // Required check
    if (rules.required && (val === undefined || val === null || val === '')) {
        errors.push({ field, message: rules.messages?.required || `${field} is required` });
        continue;
    }

    // Skip optional empty
    if (val === undefined || val === null || val === '') continue;

    // Type dispatch
    if (rules.type === 'string') val = validateString(field, val, rules, errors);
    if (rules.type === 'number') val = validateNumber(field, val, rules, errors);
    if (rules.type === 'boolean') val = validateBoolean(field, val, rules, errors);
    if (rules.type === 'date') val = validateDate(field, val, rules, errors);
    if (rules.type === 'array') val = validateArray(field, val, rules, errors, isStrictItems);

    // Allowed values (scalars only — arrays handled per-item above)
    if (val !== null && val !== undefined && rules.type !== 'array' && rules.allowedValues) {
        val = validateAllowedValues(field, val, rules, errors);
    }

    if (val !== null && val !== undefined) cleaned[field] = val;
}


// ─────────────────────────────────────────────
// RESPOND
// ─────────────────────────────────────────────

if (errors.length > 0) {
    const isFormSubmission = (msg.req?.headers?.['content-type'] || '').includes('application/x-www-form-urlencoded');
    const isFetchRequest = msg.isFetchRequest;  // set by AUTH_MIDDLEWARE

    msg.statusCode = 400;

    if (!isFetchRequest && isFormSubmission) {
        // Output 3 → form/browser redirect with errors in query string
        const errorParam = encodeURIComponent(JSON.stringify(errors));
        const path = msg.errorRedirectPath || '/app/home';
        msg.statusCode = 302;
        msg.headers = { Location: `${path}?errors=${errorParam}` };
        msg.payload = 'Redirecting...';
        return [null, null, msg];
    }

    // Output 2 → fetch / JSON error
    msg.payload = { success: false, errors };
    return [null, msg, null];
}

// Output 1 → valid
msg.payload = cleaned;
return [msg, null, null];

// ====================================================
// NAV BUILDER — UI Builder Logic
//
// A drop-in block. The code below NEVER changes between
// projects. Only NAV_CONFIG does, and that can come from
// a subflow property / env var so the same subflow can be
// dragged into any Node-RED instance untouched.
//
// INPUT
//   msg.rbac — from the RBAC subflow (output 1)
//              { userRoles: ['admin'] }  or  { userRole: 'admin' }
//
// OUTPUT  (property names unchanged — templates need no edit)
//   msg.homeButtons       — category tiles + drill-down views + search
//   msg.navButtons        — sidebar nav HTML (flat, as before)
//   msg.redirectListeners — addRedirectListener calls + page wiring
//
// CONFIG
//   env NAV_CONFIG — JSON matching DEFAULT_CONFIG below.
//                    If unset, DEFAULT_CONFIG is used.
