// --------------------------------------------------
// 3. Load config (env override → defaults)
// --------------------------------------------------
let CONFIG = DEFAULT_CONFIG;
const rawConfig = env.get('NAV_CONFIG');
if (rawConfig) {
    try {
        const parsed = typeof rawConfig === 'string' ? JSON.parse(rawConfig) : rawConfig;
        if (parsed && Array.isArray(parsed.categories) && parsed.categories.length) {
            CONFIG = parsed;
        } else {
            node.warn('Nav Builder: NAV_CONFIG has no categories[] — using defaults');
        }
    } catch (e) {
        node.warn('Nav Builder: NAV_CONFIG is not valid JSON — using defaults. ' + e.message);
    }
}

const ICON_BASE      = CONFIG.iconBase || '';
const BACK_LABEL     = CONFIG.backLabel || '← All categories';
const CATEGORIES     = CONFIG.categories || [];
const FIXED_NAV_TOP  = CONFIG.fixedNavTop || [];
const FIXED_NAV_BOT  = CONFIG.fixedNavBottom || [];
const ROLE_MAP       = CONFIG.roles || {};


// --------------------------------------------------
// 4. Resolve roles → allowed keys (union across roles)
// --------------------------------------------------
const userRoles = msg.rbac.userRoles || [msg.rbac.userRole];

const allKeys = [];
for (const role of userRoles) {
    const roleKeys = ROLE_MAP[String(role).toLowerCase()] || [];
    allKeys.push(...roleKeys);
}
const allowed = new Set(allKeys);

if (allowed.size === 0) {
    node.warn(`Nav Builder: no roles entry for [${userRoles.join(',')}] — empty UI will render`);
}

// Warn about role keys that don't exist in any category —
// otherwise a typo in roles just silently grants nothing.
const declared = new Set();
CATEGORIES.forEach(c => (c.items || []).forEach(i => declared.add(i.key)));
const unknown = [...allowed].filter(k => !declared.has(k));
if (unknown.length) {
    node.warn(`Nav Builder: roles reference unknown keys [${unknown.join(',')}]`);
}


// --------------------------------------------------
// 5. Visible categories — drop anything RBAC emptied
// --------------------------------------------------
const visible = CATEGORIES
    .map(cat => ({
        id: cat.id,
        label: cat.label,
        icon: cat.icon,
        items: (cat.items || []).filter(i => allowed.has(i.key))
    }))
    .filter(cat => cat.items.length > 0);


// --------------------------------------------------
