// --------------------------------------------------
// 7. Markup helpers
// --------------------------------------------------

// A tile in the existing house style. `extra` lets us hang
// data-cat / data-search on it without a second template.
function tileHTML(opts) {
    return `
        <div class="tile-outer tile-div ${opts.className}"${opts.extra || ''}>
            <div class="tile-inner">
                <div class="tile-content">
                    <div class="tile-icon">
                        <img src="${ICON_BASE}${opts.icon}" alt="${opts.label}">
                    </div>
                    <div class="tile-label"><span>${opts.label}${opts.sub || ''}</span></div>
                </div>
            </div>
        </div>`;
}

function navButtonHTML(b) {
    const tip = b.navLabel || b.label || b.key;
    return `
        <div class="menu-button  ${b.className} " id="${b.className}" data-href="${b.href}" data-tooltip="${tip}">
            <img src="${ICON_BASE}${b.icon}" alt="${tip}" />
        </div>`;
}

function esc(s) {
    return String(s).replace(/"/g, '&quot;');
}


// --------------------------------------------------
// 8. Home body — category tiles + one view per category
// --------------------------------------------------
function buildHomeButtons() {

    // Category grid. Falls back to the first tool's icon if
    // the category has none of its own.
    const catTiles = visible.map(cat => tileHTML({
        className: 'nb-cat-tile',
        icon: cat.icon || cat.items[0].icon,
        label: cat.label,
        sub: `<span class="nb-count">${cat.items.length} tool${cat.items.length === 1 ? '' : 's'}</span>`,
        extra: ` data-cat="${esc(cat.id)}"`
    })).join('\n');

    // One hidden view per category.
    const catViews = visible.map(cat => `
        <div class="nb-view" data-view="${esc(cat.id)}" hidden>
            <div class="nb-crumb">
                <button type="button" class="nb-back">${BACK_LABEL}</button>
                <span class="nb-crumb-title">${cat.label}</span>
            </div>
            <div class="util-buttons">
                ${cat.items.map(i => tileHTML({
                    className: i.className,
                    icon: i.icon,
                    label: i.label,
                    extra: ` data-search="${esc((i.label + ' ' + (i.navLabel || '')).toLowerCase())}"`
                })).join('\n')}
            </div>
        </div>`).join('\n');

    // Search results view — flat list, grouped by category so
    // the user still sees where a tool lives.
    const searchGroups = visible.map(cat => `
        <div class="nb-group" data-group="${esc(cat.id)}">
            <div class="nb-group-title">${cat.label}</div>
            <div class="util-buttons">
                ${cat.items.map(i => tileHTML({
                    className: i.className,
                    icon: i.icon,
                    label: i.label,
                    extra: ` data-search="${esc((i.label + ' ' + (i.navLabel || '')).toLowerCase())}"`
                })).join('\n')}
            </div>
        </div>`).join('\n');

    return `${HOME_STYLES}
        <div class="nb-search-wrap">
            <input type="text" id="nb-search" class="nb-search" placeholder="Search tools…" autocomplete="off">
        </div>

        <div class="nb-view" id="nb-categories">
            <div class="util-buttons">${catTiles}</div>
        </div>

        ${catViews}

        <div class="nb-view" id="nb-results" hidden>${searchGroups}</div>

        <div class="nb-empty" id="nb-empty" hidden>No tools match that.</div>`;
}


// --------------------------------------------------
// 9. Sidebar — flat, unchanged behaviour
// --------------------------------------------------
function buildNavButtons() {
    const dynamic = visible
        .reduce((acc, cat) => acc.concat(cat.items), [])
        .filter(i => i.nav !== false)
        .map(navButtonHTML);

    return [
        ...FIXED_NAV_TOP.map(navButtonHTML),
        ...dynamic,
        ...FIXED_NAV_BOT.map(navButtonHTML)
    ].join('\n');
}


// --------------------------------------------------
// 10. Listeners — redirects (bind by className, so one call
// covers both the tile and the sidebar button) plus the
// drill-down and search wiring.
// --------------------------------------------------
function buildRedirectListeners() {
    const targets = [
        ...FIXED_NAV_TOP,
        ...visible.reduce((acc, cat) => acc.concat(cat.items), []),
        ...FIXED_NAV_BOT
    ];

    const calls = targets
        .map(b => `addRedirectListener('${b.className}', '${b.href}');`)
        .join('\n        ');

    // Category tiles deliberately do NOT get a redirect —
    // they swap the view in place.
    const wiring = `

        /* ---- nav builder: drill-down + search ---- */
        (function () {
            var search = document.getElementById('nb-search');
            if (!search) return;   /* not the home page */

            var cats    = document.getElementById('nb-categories');
            var results = document.getElementById('nb-results');
            var empty   = document.getElementById('nb-empty');
            var views   = [].slice.call(document.querySelectorAll('.nb-view[data-view]'));

            function showCategories() {
                cats.hidden = false;
                results.hidden = true;
                empty.hidden = true;
                views.forEach(function (v) { v.hidden = true; });
            }

            function showCategory(id) {
                cats.hidden = true;
                results.hidden = true;
                empty.hidden = true;
                views.forEach(function (v) {
                    v.hidden = v.getAttribute('data-view') !== id;
                });
                window.scrollTo(0, 0);
            }

            function showResults(term) {
                cats.hidden = true;
                views.forEach(function (v) { v.hidden = true; });
                results.hidden = false;

                var hits = 0;
                results.querySelectorAll('.nb-group').forEach(function (g) {
                    var shown = 0;
                    g.querySelectorAll('.tile-div').forEach(function (el) {
                        var match = (el.getAttribute('data-search') || '').indexOf(term) > -1;
                        el.style.display = match ? '' : 'none';
                        if (match) shown++;
                    });
                    g.style.display = shown ? '' : 'none';
                    hits += shown;
                });
                empty.hidden = hits > 0;
            }

            /* Category tile → open that category */
            document.addEventListener('click', function (e) {
                var tile = e.target.closest('[data-cat]');
                if (tile) { showCategory(tile.getAttribute('data-cat')); return; }
                if (e.target.closest('.nb-back')) { search.value = ''; showCategories(); }
            });

            search.addEventListener('input', function () {
                var term = search.value.trim().toLowerCase();
                if (term) showResults(term);
                else showCategories();
            });
        })();`;

    return calls + wiring;
}


// --------------------------------------------------
// 11. Build and attach
// --------------------------------------------------
msg.homeButtons       = buildHomeButtons();
msg.navButtons        = buildNavButtons();
msg.redirectListeners = buildRedirectListeners();

msg.navBuilder = {
    roles: userRoles,
    categories: visible.map(c => ({ id: c.id, count: c.items.length })),
    keys: visible.reduce((acc, c) => acc.concat(c.items.map(i => i.key)), []),
    configSource: rawConfig ? 'NAV_CONFIG' : 'defaults'
};

return msg;

