function buildNavButtons(keys) {
    const top     = FIXED_NAV_TOP.map(navButtonHTML);
    const dynamic = keys.filter(k => NAV_BUTTONS[k]).map(k => navButtonHTML(NAV_BUTTONS[k]));
    const bottom  = FIXED_NAV_BOTTOM.map(navButtonHTML);
    return [...top, ...dynamic, ...bottom].join('\n');
}

