    msg.payload = [displayname.toUpperCase(), email || '', JSON.stringify(roles), recid];
    msg.successMessage = 'User updated successfully.';

} else if (action === 'deactivate') {
    msg.topic = "UPDATE users SET active='n', tslastupdated=NOW() WHERE recid=?";
    msg.payload = [recid];
    msg.successMessage = 'User deactivated successfully.';

} else if (action === 'reactivate') {
    msg.topic = "UPDATE users SET active='y', tslastupdated=NOW() WHERE recid=?";
    msg.payload = [recid];
    msg.successMessage = 'User reactivated successfully.';

} else {
    msg.payload = { success: false, message: 'Unknown action.' };
    msg.statusCode = 400;
    msg.skip = true;
    return msg;
}

msg.skip = false;
return msg;

msg.payload = { success: true, message: msg.successMessage };
msg.statusCode = 200;
return msg;

let rows = msg.payload.rows;

if (!Array.isArray(rows) || rows.length === 0) {
    msg.statusCode = 400;
    msg.payload = { success: false, message: 'No rows received' };
    return [null, msg];
}

let preparedRows = [];
let seenInBatch = {};

for (let i = 0; i < rows.length; i++) {
    let row = rows[i];
    if (!row.username || !row.displayname || !Array.isArray(row.roles) || row.roles.length === 0) {
        msg.statusCode = 400;
        msg.payload = { success: false, message: `Row ${i + 1}: Username, Display Name and Roles are required` };
        return [null, msg];
    }

    let key = row.username.trim().toLowerCase();
    let isDuplicateInBatch = seenInBatch.hasOwnProperty(key);
    seenInBatch[key] = true;

    preparedRows.push({
        userid: row.userid || null,
        username: row.username.trim(),
        userdisplayname: row.displayname.trim().toUpperCase(),
        userrole: JSON.stringify(row.roles),
        email: row.email || null,
        batchDuplicate: isDuplicateInBatch
    });
}

msg.queue = preparedRows;
msg.currentIndex = 0;
msg.results = [];

return [msg, null];

// If all rows processed, go to final response
if (msg.currentIndex >= msg.queue.length) {
    return [msg, null];
}

let row = msg.queue[msg.currentIndex];
msg.currentRow = row;

// Skip DB check entirely if flagged as intra-batch duplicate
if (row.batchDuplicate) {
    msg.results.push({
        username: row.username,
        displayname: row.userdisplayname,
        status: 'skipped',
        message: 'Skipped - duplicate within submitted batch'
    });
    msg.currentIndex++;
    return [null, msg]; // loop back
}

// Proceed to DB duplicate check
msg.payload = [row.username];
return [null, msg];

let exists = msg.payload.length > 0;
let row = msg.currentRow;

if (exists) {
    msg.results.push({
        username: row.username,
        displayname: row.userdisplayname,
        status: 'skipped',
        message: 'Skipped — username already exists in database'
    });
    msg.currentIndex++;
    return [msg, null]; // skip insert, loop back
}

msg.userdetails = {
    userid: row.userid,
    username: row.username,
    userdisplayname: row.userdisplayname,
    userrole: row.userrole,
    email: row.email,
    password: 'User@123',
    pin: '1234'
};

return [null, msg]; // proceed to insert

let row = msg.currentRow;

msg.results.push({
    username: row.username,
    displayname: row.userdisplayname,
    status: 'created',
    message: 'Created successfully'
});

msg.currentIndex++;
return msg;

let results = msg.results;
let created  = results.filter(r => r.status === 'created').length;
let skipped  = results.filter(r => r.status === 'skipped').length;

msg.payload = {
    success: true,
    summary: {
        total:   results.length,
        created: created,
        skipped: skipped
    },
    results: results
};

return msg;

